namespace MisakTabs
{
    // which parts this build has (Mišák Tabs = all; the single-part mods are generated by Tools/split.py)
    public static class BuildInfo
    {
        public const string Name = "Mišák Tabs";
        public const bool Split = false;
        private static readonly string[] Parts = null;
        public static bool Has(string field) => Parts == null || System.Array.IndexOf(Parts, field) >= 0;
    }
}
